package com.litha.api.controller;
import com.litha.api.model.StoneIdentification; import com.litha.api.repository.StoneIdentificationRepository; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/stone-identifications") public class StoneIdentificationController extends CrudController<StoneIdentification> { private final StoneIdentificationRepository repo; public StoneIdentificationController(StoneIdentificationRepository repo) { this.repo = repo; } protected JpaRepository<StoneIdentification,Long> repository() { return repo; } @GetMapping(params="stoneId") public List<StoneIdentification> byStone(@RequestParam Long stoneId) { return repo.findByStoneId(stoneId); } }
